import {mountGallery,connectorName,connectorHelp} from './gallery.js';
import {getVisionMetadata,detectConnectors} from './vision.js';
import {extractSpecifications,normalizePart,specExamples} from './specifications.js';
import {mountAssistant} from './assistant.js';
import {analyzeMeasurements} from './measurements.js';
import {steps,catalog,initialConfig,evaluate,connectorTypes,assessPerformance} from './data.js';
import {createScene} from './scene.js';
const $=s=>document.querySelector(s);let current=0,done=new Set(),config={...initialConfig},scene,exploded=false,marks=[],corner=null,photoUrl=null,assistant;
let customParts=[];
try{const stored=JSON.parse(localStorage.getItem('buildacademy-parts-v1')||'[]');if(Array.isArray(stored))for(const entry of stored.slice(0,40)){try{if(!/^custom-[a-f0-9-]{36}$/.test(entry.id))continue;const validated=normalizePart(entry.category,entry.originalName,entry.source,entry.fields);catalog[entry.category].options.push({...validated,id:entry.id});customParts.push(entry)}catch{}}}catch{}
try{let saved=JSON.parse(localStorage.getItem('buildacademy-state-v1')||'null');if(saved&&Object.keys(catalog).every(k=>catalog[k].options.some(o=>o.id===({...initialConfig,...saved.config})[k]))){config={...initialConfig,...saved.config};if(Array.isArray(saved.reviewed))done=new Set(saved.reviewed.filter(n=>Number.isInteger(n)&&n>=0&&n<steps.length))}}catch{}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function save(){try{localStorage.setItem('buildacademy-state-v1',JSON.stringify({config,reviewed:[...done]}))}catch{toast('Tu navegador no permite guardar el avance.')}}
function setView(view){if(!['guide','compat','photo'].includes(view))throw new Error('Sección desconocida');document.querySelectorAll('.view').forEach(el=>{el.hidden=el.id!==view;el.classList.toggle('active',el.id===view)});document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-selected',b.dataset.view===view)});}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function renderStep(){const s=steps[current];$('#steps').innerHTML=steps.map((s,i)=>`<button class="step ${i===current?'active':''} ${done.has(i)?'done':''}" data-step="${i}" ${i===current?'aria-current="step"':''}><span class="num">${done.has(i)?'✓':String(i+1).padStart(2,'0')}</span><span class="step-name">${s.short}<small>${s.sub}</small></span></button>`).join('');document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>goStep(Number(b.dataset.step)));renderGuideContext();$('#step-number').textContent=`PASO ${String(current+1).padStart(2,'0')} / ${steps.length}`;$('#step-title').textContent=s.title;$('#step-description').textContent=s.description;$('#step-why').textContent=s.why;$('#step-check').textContent=s.check;$('#part-label').textContent=s.label;$('#complete').innerHTML=done.has(current)?'Revisado <span>✓</span>':'Marcar como revisado <span>✓</span>';$('#complete').classList.toggle('done',done.has(current));$('#complete').setAttribute('aria-pressed',done.has(current));$('#count').textContent=`${done.size} / ${steps.length}`;$('#progress').style.width=`${done.size/steps.length*100}%`;$('#prev').disabled=current===0;$('#next').disabled=current===steps.length-1;}
function goStep(i){if(!Number.isInteger(i)||i<0||i>=steps.length)throw new Error('Paso inválido');current=i;renderStep();scene?.setStep(i)}
$('#prev').onclick=()=>goStep(current-1);$('#next').onclick=()=>goStep(current+1);$('#complete').onclick=()=>{if(done.has(current)){done.delete(current)}else{done.add(current);toast(done.size===steps.length?'¡Recorrido revisado! El montaje real requiere su propia verificación.':'Paso marcado como revisado')}save();renderStep()};$('#reset-progress').onclick=()=>{done.clear();save();goStep(0);toast('Recorrido reiniciado')};$('#replay').onclick=()=>scene?.replay();$('#reset-camera').onclick=()=>scene?.reset();$('#explode').onclick=()=>{exploded=!exploded;scene?.explode(exploded);$('#explode').setAttribute('aria-pressed',exploded);$('#explode').textContent=exploded?'Vista ensamblada':'Vista separada'};
renderStep();try{scene=createScene($('#scene'),goStep)}catch(e){$('#scene').innerHTML='<p class="scene-error">No se pudo iniciar el visor 3D. Probá un navegador con WebGL habilitado. Podés seguir consultando los pasos y la compatibilidad.</p>';$('#replay').disabled=true;$('#explode').disabled=true;$('#reset-camera').disabled=true;console.error(e)}
function renderSelectors(){$('#selectors').replaceChildren();for(const [key,c] of Object.entries(catalog)){let label=document.createElement('label');label.htmlFor=`select-${key}`;label.textContent=c.label;let select=document.createElement('select');select.id=`select-${key}`;select.innerHTML=c.options.map(o=>`<option value="${o.id}">${o.name}</option>`).join('');select.value=config[key];select.onchange=()=>changeConfig({[key]:select.value});$('#selectors').append(label,select)}}
renderSelectors();
function renderResults(){let results=evaluate(config),fails=results.filter(r=>r.status==='fail').length;$('#compat-summary').className=`result-summary ${fails?'bad':''}`;$('#compat-summary').innerHTML=fails?`${fails} ${fails===1?'incompatibilidad detectada':'incompatibilidades detectadas'}<small>Revisá las piezas señaladas antes de continuar.</small>`:`${results.filter(r=>r.status==='pass').length} comprobaciones coinciden<small>${results.filter(r=>r.status==='unknown').length} verificaciones con información pendiente.</small>`;$('#results').innerHTML=results.map(r=>`<div class="result ${r.status}"><span class="result-icon">${r.status==='pass'?'✓':r.status==='fail'?'×':'?'}</span><div><h4>${r.name}</h4><p>${r.detail}</p></div></div>`).join('');renderConfigurationDetails()}
function changeConfig(next){for(const k of Object.keys(next)){if(!catalog[k]||!catalog[k].options.some(o=>o.id===next[k]))throw new Error('Componente inválido')}const changed=Object.keys(next).some(k=>config[k]!==next[k]);config={...config,...next};if(changed&&done.size){done.clear();toast('Configuración actualizada. Revisá los pasos para estas piezas.')}save();for(const k of Object.keys(catalog))$(`#select-${k}`).value=config[k];renderResults();renderStep();scene?.setConfig(config);if(changed){measurements=null;$('#measurement-result').textContent='Configuración cambiada. Importá una captura de este equipo para analizarla.';assistant?.resetContext()}}
$('#intel-example').onclick=()=>changeConfig({board:'intel',cpu:'intelcpu',ram:'ddr4',ssd:'nvme',gpu:'rx7600'});$('#usage').onchange=renderPerformance;
$('#bad-example').onclick=()=>changeConfig({board:'am5',cpu:'intelcpu',ram:'ddr4',ssd:'sata'});$('#good-example').onclick=()=>changeConfig(initialConfig);renderResults();
$('#connector-type').innerHTML=connectorTypes.map(t=>`<option value="${t}">${connectorName(t)}</option>`).join('');
function clearCorner(){corner=null;renderMarks();if(photoUrl&&$('#connector-type').closest('details').open)$('#photo-status').textContent='Marcá dos esquinas opuestas para señalar un conector.'}$('#cancel-mark').onclick=clearCorner;document.addEventListener('keydown',e=>{if(e.key==='Escape')clearCorner()});
let photoRequest=0;
async function loadPhoto(f,source=null){
 const serial=++photoRequest;
 if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>15*1024*1024)throw Error('Elegí un archivo JPG, PNG o WebP de hasta 15 MB.');
 const url=URL.createObjectURL(f),test=new Image();
 try{test.src=url;await test.decode();if(serial!==photoRequest){URL.revokeObjectURL(url);return false}if(test.naturalWidth*test.naturalHeight>40000000)throw Error('La imagen supera los 40 megapíxeles.');if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=url;marks=[];corner=null;$('#photo-image').src=url;await $('#photo-image').decode();$('#photo-image').alt=source?.name||'Motherboard cargada';$('#annotations').setAttribute('viewBox',`0 0 ${test.naturalWidth} ${test.naturalHeight}`);$('#photo-area').hidden=false;$('#photo-status').textContent=source?'Foto elegida: '+source.name:'Foto lista. Tocá Detectar conectores para explorarla.';$('#photo-source').replaceChildren();if(source){const credit=document.createElement('a');credit.href=source.source;credit.target='_blank';credit.rel='noopener noreferrer';credit.textContent=`Foto: ${source.author} · ${source.license} · Ver original`;$('#photo-source').append(credit)}renderMarks();updateVisionButton();return true}catch(e){URL.revokeObjectURL(url);throw e}
}
$('#photo-input').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await loadPhoto(f)}catch(err){$('#photo-status').textContent=err.message}finally{e.target.value=''}};
$('#annotations').addEventListener('click',e=>{if(!$('#connector-type').closest('details').open)return;const r=e.currentTarget.getBoundingClientRect(),img=$('#photo-image');let p={x:(e.clientX-r.left)/r.width*img.naturalWidth,y:(e.clientY-r.top)/r.height*img.naturalHeight};if(!corner){corner=p;$('#photo-status').textContent='Ahora marcá la esquina opuesta. Escape para cancelar.';renderMarks();return}let x=Math.min(p.x,corner.x),y=Math.min(p.y,corner.y),w=Math.abs(p.x-corner.x),h=Math.abs(p.y-corner.y);if(w<8||h<8){toast('Elegí una zona un poco más grande.');return}marks.push({type:$('#connector-type').value,x,y,w,h});clearCorner()});
function renderMarks(){const img=$('#photo-image'),stroke=Math.max(2,(img.naturalWidth||1000)/350),font=Math.max(15,(img.naturalWidth||1000)/45);$('#annotations').innerHTML=marks.map((m,i)=>`<g><rect x="${m.x}" y="${m.y}" width="${m.w}" height="${m.h}" fill="#bbef7522" stroke="#a8ed5c" stroke-width="${stroke}"/><text x="${m.x+4}" y="${m.y+font}" font-size="${font}" fill="white" stroke="#172719" stroke-width="${stroke*.6}" paint-order="stroke">${i+1}. ${connectorName(m.type)}</text></g>`).join('')+(corner?`<circle cx="${corner.x}" cy="${corner.y}" r="${stroke*3}" fill="#eaaa5a"/>`:'');$('#annotation-list').innerHTML=marks.length?marks.map((m,i)=>`<div class="annotation-item"><span>${i+1}. ${connectorName(m.type)}<br><small>${m.origin==='model'?'Detectado en la foto':'Señalado a mano'}</small><p>${connectorHelp[m.type]||'Revisá el uso y el cable correcto en el manual de la placa.'}</p></span><button data-delete="${i}" aria-label="Eliminar marca ${i+1}">Eliminar</button></div>`).join(''):'<p class="muted">Todavía no hay marcas.</p>';document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{marks.splice(Number(b.dataset.delete),1);renderMarks()})}renderMarks();
// Optional browser-native agent interface shares the same validated UI actions.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_buildacademy_state',description:'Leer paso actual, avance y reglas de compatibilidad.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({step:current+1,reviewed:[...done].map(n=>n+1),config,results:evaluate(config)})},{name:'navigate_assembly_step',description:'Abrir un paso educativo sin marcarlo como revisado.',inputSchema:{type:'object',properties:{step:{type:'integer',minimum:1,maximum:8}},required:['step'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.step)||input.step<1||input.step>8)throw new Error('Paso inválido');setView('guide');goStep(input.step-1);return{step:current+1,title:steps[current].title}}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}

function renderPerformance(){
 const assessment=assessPerformance(config,$('#usage').value);
 $('#performance-results').innerHTML=`<h3>${assessment.title}</h3><p class="muted">${assessment.detail}</p>`+assessment.items.map(item=>`<div class="performance-item"><h4>${item.title}</h4><p>${item.text}</p></div>`).join('');
}
function renderConfigurationDetails(){
 let summary=document.querySelector("#build-summary");if(!summary){summary=document.createElement("p");summary.id="build-summary";summary.className="print-summary";document.querySelector("#compat").prepend(summary)}summary.textContent=Object.entries(catalog).map(([k,c])=>c.label+": "+c.options.find(o=>o.id===config[k]).name).join("\n");
 $('#source-links').innerHTML='<span>Fichas de referencia · Catálogo consultado el 21/09/2026. Las piezas aportadas requieren revisión.</span>'+Object.keys(catalog).filter(k=>catalog[k].options.find(o=>o.id===config[k]).source).map(k=>{const item=catalog[k].options.find(o=>o.id===config[k]);return `<a href="${item.source}" target="_blank" rel="noopener noreferrer">${item.name} ↗</a>`}).join('');
 renderPerformance();
}
function renderGuideContext(){
 const board=catalog.board.options.find(o=>o.id===config.board),cpu=catalog.cpu.options.find(o=>o.id===config.cpu),gpu=catalog.gpu.options.find(o=>o.id===config.gpu);
 const failed=evaluate(config).filter(r=>r.status==='fail');
 $('#build-context').innerHTML=`<div><strong>${board.name}</strong><span>${cpu.name} · ${gpu.name}</span></div><button id="edit-config" class="secondary">Cambiar componentes</button><p>${failed.length?'Hay incompatibilidades: usá la guía solo para explorar.':'Configuración vinculada · Verificación completa pendiente.'} El modelo 3D es genérico, no una réplica de estas piezas.</p>`;
 $('#edit-config').onclick=()=>setView('compat');
 let context=current===1?`${cpu.name}: socket ${cpu.socket}. La placa seleccionada utiliza ${board.socket}.`:current===2?`Esta placa utiliza ${board.memory}. Verificá en el manual las posiciones para tu kit.`:current===3?(config.ssd==='sata'?(board.id==='intel'?'M.2 SATA: usá M2_2; SATA8 quedará deshabilitado.':'El SSD M.2 SATA seleccionado no es compatible con los M.2 de esta placa.'):'El perfil seleccionado es NVMe 2280. Identificá M.2_1 o M.2_2 en el manual.'):current===4?`El kit debe admitir ${board.socket}. ${catalog.cooler.options.find(o=>o.id===config.cooler).name}; revisá el manual específico de ese cooler.`:current===5?'Esta motherboard utiliza formato ATX. Comprobá soporte y separadores del gabinete.':current===6?`${gpu.name}: ${gpu.length} mm de largo, ${gpu.thickness} mm de espesor y ${gpu.pcie8} conector PCIe de 8 pines. Montaje horizontal en la ranura principal.`:current===7?board.power:'Consultá las instrucciones del modelo seleccionado antes del montaje real.';
 let node=$('#step-context');if(!node){node=document.createElement('div');node.id='step-context';node.className='step-context';$('.instruction').insertBefore(node,$('#complete'))}
 const guidePart=current===4?catalog.cooler.options.find(o=>o.id===config.cooler):current===5?catalog.case.options.find(o=>o.id===config.case):current===6?gpu:current===7?catalog.psu.options.find(o=>o.id===config.psu):board;
 node.innerHTML=`<p>${context}</p>`+(guidePart.manual||guidePart.source?`<a href="${guidePart.manual||guidePart.source}" target="_blank" rel="noopener noreferrer">Abrir ${guidePart.manual?'manual':'ficha'} de ${guidePart.name} ↗</a>`:'<p>Falta el manual del componente elegido. Incorporá sus datos antes del montaje.</p>');
}

assistant=mountAssistant(()=>({config:{...config},step:current,usage:$('#usage').value,measurements,fpsCap:$('#fps-cap').checked}));
scene?.setConfig(config);
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#export-build').onclick=()=>download('buildacademy-configuracion.json',JSON.stringify({version:2,config,reviewed:[...done],customParts},null,2));
$('#import-build').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw new Error('El archivo es demasiado grande.');const data=JSON.parse(await file.text());const imported=[];if(data.customParts!==undefined){if(!Array.isArray(data.customParts)||data.customParts.length>40)throw new Error('Fichas inválidas.');for(const entry of data.customParts){if(!/^custom-[a-f0-9-]{36}$/.test(entry.id))throw new Error('Identificador de ficha inválido.');const item=normalizePart(entry.category,entry.originalName,entry.source,entry.fields);imported.push({entry,item})}}if(data.version!==2||!data.config||!Object.keys(catalog).every(k=>(catalog[k].options.some(o=>o.id===data.config[k])||imported.some(x=>x.entry.category===k&&x.entry.id===data.config[k]))))throw new Error('Configuración desconocida o incompleta.');for(const {entry,item} of imported){if(!catalog[entry.category].options.some(o=>o.id===entry.id)){catalog[entry.category].options.push({...item,id:entry.id});customParts.push(entry)}}localStorage.setItem('buildacademy-parts-v1',JSON.stringify(customParts));renderSelectors();renderCustomParts();changeConfig(Object.fromEntries(Object.keys(catalog).map(k=>[k,data.config[k]])));done=new Set(Array.isArray(data.reviewed)?data.reviewed.filter(n=>Number.isInteger(n)&&n>=0&&n<steps.length):[]);save();renderStep();$('#transfer-status').textContent='Configuración restaurada. Las revisiones reflejan el archivo importado, no una inspección física.'}catch(err){$('#transfer-status').textContent=err.message}finally{e.target.value=''}};
$('#print-build').onclick=()=>window.print();
$('#export-annotations').onclick=()=>{if(!photoUrl)return toast('Cargá una foto primero.');download('conectores.json',JSON.stringify({version:1,width:$('#photo-image').naturalWidth,height:$('#photo-image').naturalHeight,origin:marks.length&&marks.every(m=>m.origin==='model')?'model':marks.some(m=>m.origin==='model')?'mixed':'manual',classes:[...new Set([...connectorTypes,...(visionMetadata?.classes||[])])],modelVersion:visionMetadata?.version||null,annotations:marks.map(m=>({...m,origin:m.origin||'manual',confidence:m.confidence??null}))},null,2))};
$('#export-yolo').onclick=()=>{if(!photoUrl)return toast('Cargá una foto primero.');const w=$('#photo-image').naturalWidth,h=$('#photo-image').naturalHeight;download('motherboard.txt',marks.filter(m=>m.origin!=='model').map(m=>[connectorTypes.indexOf(m.type),(m.x+m.w/2)/w,(m.y+m.h/2)/h,m.w/w,m.h/h].join(' ')).join('\n'),'text/plain');toast('YOLO exporta sólo marcas manuales. Guardá el TXT con el nombre base de la foto.')};
let measurements=null;
function renderMeasurements(){if(!measurements)return;const target=$('#measurement-result');target.replaceChildren();try{const result=analyzeMeasurements(measurements,{fpsCap:$('#fps-cap').checked});const title=document.createElement('h4');title.textContent=`${result.count} muestras · media ${result.averages.fps} FPS`;target.append(title);for(const text of [...result.findings,result.method]){const p=document.createElement('p');p.textContent=text;target.append(p)}}catch(err){target.textContent=err.message}}
$('#measurement-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3000000)throw new Error('Máximo 3 MB.');const data=JSON.parse(await file.text());measurements=data.samples;analyzeMeasurements(measurements);renderMeasurements()}catch(err){measurements=null;$('#measurement-result').textContent=err.message}finally{e.target.value=''}};
$('#fps-cap').onchange=renderMeasurements;
$('#measurement-template').onclick=()=>download('formato-mediciones.json',JSON.stringify({description:'Reemplazá samples por al menos 30 muestras reales. fps: cuadros/segundo; gpu, cpuMax (núcleo/hilo más ocupado), ram y vram: porcentajes 0..100. No mezclar equipos ni escenas.',samples:[]},null,2));


let specDraft=null;
function resetSpec(){specDraft=null;$('#spec-save').disabled=true;$('#spec-preview').textContent=''}
function loadSpec(){resetSpec();$('#spec-text').value=specExamples[$('#spec-category').value];$('#spec-sockets').hidden=$('#spec-category').value!=='cooler'}
$('#spec-category').onchange=loadSpec;for(const id of ['spec-name','spec-source','spec-text','spec-am5','spec-lga'])$('#'+id).addEventListener('input',resetSpec);loadSpec();
$('#spec-extract').onclick=()=>{resetSpec();try{const category=$('#spec-category').value,fields=extractSpecifications(category,$('#spec-text').value);if(category==='cooler')fields.sockets=[$('#spec-am5').checked?'AM5':null,$('#spec-lga').checked?'LGA1700':null].filter(Boolean);const item=normalizePart(category,$('#spec-name').value,$('#spec-source').value,fields);specDraft={category,item,fields,originalName:$('#spec-name').value,source:$('#spec-source').value};$('#spec-preview').textContent=JSON.stringify(item,null,2);$('#spec-save').disabled=false}catch(err){$('#spec-preview').textContent=err.message}};
$('#spec-save').onclick=()=>{if(!specDraft)return;if(customParts.length>=40)return toast('Llegaste al límite de 40 fichas locales.');const {category,item,...record}=specDraft,id='custom-'+crypto.randomUUID();try{localStorage.setItem('buildacademy-parts-v1',JSON.stringify([...customParts,{...record,category,id}]))}catch{return toast('No se pudo guardar la ficha.')}customParts.push({...record,category,id});catalog[category].options.push({...item,id});renderSelectors();changeConfig({[category]:id});resetSpec();renderCustomParts();toast('Ficha incorporada. Sus datos requieren verificación con el fabricante.')};
function renderCustomParts(){
 const list=$('#custom-parts-list');list.replaceChildren();
 for(const entry of customParts){const row=document.createElement('div');row.className='annotation-item';const text=document.createElement('span');text.textContent=entry.originalName;const button=document.createElement('button');button.textContent='Eliminar ficha';button.setAttribute('aria-label',`Eliminar ficha ${entry.originalName}`);button.onclick=()=>{const remaining=customParts.filter(p=>p.id!==entry.id);try{localStorage.setItem('buildacademy-parts-v1',JSON.stringify(remaining))}catch{return toast('No se pudo guardar el cambio.')}if(config[entry.category]===entry.id)changeConfig({[entry.category]:initialConfig[entry.category]});catalog[entry.category].options=catalog[entry.category].options.filter(p=>p.id!==entry.id);customParts=remaining;renderSelectors();renderCustomParts();toast('Ficha eliminada del catálogo local.')};row.append(text,button);list.append(row)}
}renderCustomParts();

let visionMetadata=null,detectBusy=false;
function updateVisionButton(){$('#detect-connectors').disabled=!photoUrl||!visionMetadata?.ready||detectBusy}
const visionReady=getVisionMetadata().then(metadata=>{visionMetadata=metadata;if(metadata.ready){$('#vision-notice').textContent='Podemos señalar el lugar del procesador, la memoria, las tarjetas y la alimentación. Revisá los resultados: pueden tener errores u omitir conexiones. La foto no confirma compatibilidad.';$('#vision-status').textContent='Elegí una foto para reconocer sus conexiones.'}else{$('#vision-status').textContent=metadata.reason||'Todavía no hay pesos entrenados.'}updateVisionButton()}).catch(()=>{$('#vision-status').textContent='No se pudo consultar el modelo. El marcado manual sigue disponible.'});
async function runDetection(){if(!photoUrl||!visionMetadata?.ready||detectBusy)return;const original=photoUrl;detectBusy=true;updateVisionButton();$('#vision-status').textContent='Cargando modelo y analizando la foto…';const start=performance.now();try{const detections=await detectConnectors($('#photo-image'),visionMetadata,0.5);if(original!==photoUrl){$('#vision-status').textContent='La foto cambió. Ejecutá la detección nuevamente.';return}marks=[...marks.filter(m=>m.origin!=='model'),...detections];corner=null;renderMarks();$('#vision-status').textContent=detections.length?`${detections.length} posibles conexiones señaladas. Revisá las marcas y comparalas con el manual de tu placa.`:'No encontramos conexiones claras. Probá una foto frontal y nítida o señalalas a mano.'}catch(err){$('#vision-status').textContent='No se pudo ejecutar la detección: '+err.message}finally{detectBusy=false;updateVisionButton()}};

$('#detect-connectors').onclick=runDetection;
mountGallery(async item=>{
 if(detectBusy)throw Error('Esperá a que termine el análisis actual.');
 const response=await fetch(item.image,{signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('Foto no disponible');
 const blob=await response.blob();if(await loadPhoto(blob,item)){await visionReady;await runDetection();$('#photo-area').scrollIntoView({behavior:'smooth',block:'center'})}
});
